sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var body = request.body.data;

    // -----------------------------
    // Mandatory field validation
    // -----------------------------

    var mandatoryFields = [
        "number",
        "caller",
        "from",
        "destination",
        "startdate",
        "return",
        "travel_type",
        "short_description"
    ];

    for (var i = 0; i < mandatoryFields.length; i++) {

        var field = mandatoryFields[i];

        if (body[field] === undefined ||
            body[field] === null ||
            body[field].toString().trim() === "") {

            response.setStatus(400);
            return {
                "status": "error",
                "message": field + " is mandatory"
            };
        }
    }


    // -----------------------------
    // Validate return field
    // -----------------------------

    if (typeof body.return !== "boolean") {

        response.setStatus(400);
        return {
            "status": "error",
            "message": "return must be true or false"
        };
    }


    // -----------------------------
    // If return = true
    // returndate is mandatory
    // -----------------------------

    if (body.return === true) {

        if (body.returndate === undefined ||
            body.returndate === null ||
            body.returndate.toString().trim() === "") {

            response.setStatus(400);
            return {
                "status": "error",
                "message": "returndate is mandatory when return is true"
            };
        }
    }


    // -----------------------------
    // If return = false
    // returndate should not be sent
    // -----------------------------

    if (body.return === false && body.returndate) {

        response.setStatus(400);
        return {
            "status": "error",
            "message": "Do not provide returndate when return is false"
        };
    }


    // -----------------------------
    // Validate travel type
    // -----------------------------

    var travelType = body.travel_type.toString().toLowerCase();

    if (travelType !== "domestic" &&
        travelType !== "international") {

        response.setStatus(400);
        return {
            "status": "error",
            "message": "travel_type must be domestic or international"
        };
    }


    // -----------------------------
    // International validation
    // -----------------------------

    if (travelType === "international") {

        if (!body.passport_details ||
            body.passport_details.toString().trim() === "") {

            response.setStatus(400);
            return {
                "status": "error",
                "message": "passport_details is mandatory for international travel"
            };
        }

        if (!body.visa_details ||
            body.visa_details.toString().trim() === "") {

            response.setStatus(400);
            return {
                "status": "error",
                "message": "visa_details is mandatory for international travel"
            };
        }
    }


    // -----------------------------
    // Check duplicate number
    // -----------------------------

    var checkNumber = new GlideRecord(
        "x_2166443_info_t_0_travelbooking"
    );

    checkNumber.addQuery("number", body.number);
    checkNumber.query();

    if (checkNumber.next()) {

        response.setStatus(409);

        return {
            "status": "error",
            "message": "Travel booking with this number already exists"
        };
    }


    // -----------------------------
    // Create record
    // -----------------------------

    var gr = new GlideRecord(
        "x_2166443_info_t_0_travelbooking"
    );

    gr.initialize();

    gr.number = body.number;
    gr.caller = body.caller;
    gr.from = body.from;
    gr.destination = body.destination;
    gr.startdate = body.startdate;
    gr.return = body.return;
    gr.travel_type = travelType;
    gr.short_description = body.short_description;


    // Return date only when return = true
    if (body.return === true) {
        gr.returndate = body.returndate;
    }


    // International fields
    if (travelType === "international") {

        gr.passport_details = body.passport_details;
        gr.visa_details = body.visa_details;
    }


    // Insert record
    var sysId = gr.insert();


    // -----------------------------
    // Insert failed
    // -----------------------------

    if (!sysId) {

        response.setStatus(500);

        return {
            "status": "error",
            "message": "Failed to create travel booking"
        };
    }


    // -----------------------------
    // Success response
    // -----------------------------

    response.setStatus(201);

    return {
        "status": "success",
        "message": "Travel booking created successfully",
        "sys_id": sysId,
        "number": gr.getValue("number")
    };

})(request, response);
